package main

import (
	"fmt"
	"regexp"
)

func main() {
	re := regexp.MustCompile(`https://[a-zA-Z0-9-]+\.trycloudflare\.com`)
	samples := []string{
		"2024-01-01T00:00:00Z INF |  https://random-name-here.trycloudflare.com  |",
		"2024-01-01T00:00:00Z INF |  https://abcd-1234-efgh.trycloudflare.com                |",
		"unrelated line with no url",
	}
	for _, s := range samples {
		fmt.Printf("%q => %q\n", s, re.FindString(s))
	}
}
EOF

